-- Schema-only reporting fixture; no production records, triggers, or credentials.
CREATE TABLE public.marketing_commission_withdrawals (id uuid PRIMARY KEY,marketing_partner_id uuid,amount numeric(12,2),status character varying(20),bank_name character varying(50),bank_account_number character varying(50),bank_account_name character varying(150),notes text,reviewed_by uuid,reviewed_at timestamp with time zone,created_at timestamp with time zone,updated_at timestamp with time zone);
CREATE TABLE public.marketing_partners (id uuid PRIMARY KEY,full_name character varying(150),phone character varying(30),email character varying(100),city_area character varying(100),referral_code character varying(50),bank_name character varying(50),bank_account_number character varying(50),bank_account_name character varying(150),experience_notes text,commission_rate numeric(10,2),total_tenants_acquired integer,total_receipts_generated integer,total_commission_earned numeric(12,2),commission_paid numeric(12,2),status character varying(30),notes_admin text,created_at timestamp with time zone,updated_at timestamp with time zone,user_id uuid,username character varying(100));
CREATE TABLE public.saas_billings (id uuid PRIMARY KEY,warkop_id uuid,tanggal date,total_transactions integer,tagihan_pokok numeric(12,2),kode_unik integer,total_tagihan numeric(12,2),status_bayar text,bukti_transfer_url text,ocr_raw_text text,grace_until timestamp with time zone,created_at timestamp with time zone);
CREATE TABLE public.shifts (id uuid PRIMARY KEY,warkop_id uuid,opened_by uuid,opened_at timestamp with time zone,closed_at timestamp with time zone,status text,total_cash_expected numeric(12,2),actual_cash_deposited numeric(12,2),difference numeric(12,2),notes text,device_id uuid,last_activity_at timestamp with time zone);
CREATE TABLE public.tenant_applications (id uuid PRIMARY KEY,marketing_partner_id uuid,business_name character varying(150),owner_name character varying(150),owner_phone character varying(30),province character varying(100),city_regency character varying(150),status character varying(20),review_notes text,reviewed_at timestamp with time zone,reviewed_by uuid,warkop_id uuid,created_at timestamp with time zone,updated_at timestamp with time zone,address text);
CREATE TABLE public.transaction_items (id uuid PRIMARY KEY,transaction_id uuid,menu_id uuid,nama_menu character varying(150),harga_satuan numeric(12,2),qty integer,notes text);
CREATE TABLE public.transactions (id uuid PRIMARY KEY,warkop_id uuid,shift_id uuid,waiter_shift_id uuid,waiter_name character varying(100),table_number character varying(20),nomor_antrean integer,total_harga numeric(12,2),payment_method text,payment_proof_url text,status_pesanan text,created_at timestamp with time zone,synced_at timestamp with time zone,customer_access_token_hash character(64),idempotency_key uuid,confirmed_at timestamp with time zone,updated_at timestamp with time zone);
CREATE TABLE public.warkop_members (id uuid PRIMARY KEY,warkop_id uuid,user_id uuid,username character varying(100),role text,created_at timestamp with time zone,display_name character varying(150),is_active boolean);
CREATE TABLE public.warkops (id uuid PRIMARY KEY,nama character varying(150),slug character varying(100),qris_image_url text,queue_dismiss_seconds integer,unique_code_range_start integer,unique_code_range_end integer,offline_limit_hours integer,is_active boolean,created_at timestamp with time zone,updated_at timestamp with time zone,marketing_agent_id uuid,marketing_commission_per_receipt numeric(10,2),province character varying(100),city_regency character varying(150),owner_name character varying(150),owner_phone character varying(30),qris_merchant_name character varying(180),logo_url text,history_pin_hash text,history_pin_salt text,address text);
